#include "cudaforge/kernels.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
using Clock=std::chrono::steady_clock;
void check(cudaError_t e){CUDAFORGE_CUDA_CHECK(e);}
template<class T> struct Device {T* p=nullptr;explicit Device(std::size_t n){if(n)check(cudaMalloc(reinterpret_cast<void**>(&p),n*sizeof(T)));}~Device(){if(p)cudaFree(p);}Device(const Device&)=delete;Device& operator=(const Device&)=delete;};
struct Events {cudaEvent_t start{},stop{};Events(){check(cudaEventCreate(&start));check(cudaEventCreate(&stop));}~Events(){cudaEventDestroy(start);cudaEventDestroy(stop);}};
double elapsed(cudaEvent_t a,cudaEvent_t b){float ms=0;check(cudaEventElapsedTime(&ms,a,b));return ms;}
double median(const std::vector<double>&v){const auto mid=v.size()/2;return v.size()%2?v[mid]:(v[mid-1]+v[mid])*0.5;}
template<class F> std::vector<double> event_samples(F&& f,int reps){f();check(cudaDeviceSynchronize());Events e;std::vector<double> v;v.reserve(reps);for(int i=0;i<reps;++i){check(cudaEventRecord(e.start));f();check(cudaEventRecord(e.stop));check(cudaEventSynchronize(e.stop));v.push_back(elapsed(e.start,e.stop));}std::sort(v.begin(),v.end());return v;}
template<class F> double host_median(F&&f,int reps){f();check(cudaDeviceSynchronize());std::vector<double>v;for(int i=0;i<reps;++i){auto a=Clock::now();f();check(cudaDeviceSynchronize());auto b=Clock::now();v.push_back(std::chrono::duration<double,std::milli>(b-a).count());}std::sort(v.begin(),v.end());return median(v);}
template<class F> double cpu_median(F&&f,int reps){f();std::vector<double>v;for(int i=0;i<reps;++i){auto a=Clock::now();f();auto b=Clock::now();v.push_back(std::chrono::duration<double,std::milli>(b-a).count());}std::sort(v.begin(),v.end());return median(v);}
void emit(std::ofstream&out,const char*alg,const char*impl,const char*gpu,std::size_t n,int reps,double kernel,double h2d,double d2h,double e2e,double cpu){out<<alg<<','<<impl<<",\""<<gpu<<"\","<<n<<','<<reps<<','<<std::setprecision(9)<<kernel<<','<<h2d<<','<<d2h<<','<<e2e<<','<<cpu<<','<<(cpu/e2e)<<'\n';}
void run_vector(const char*gpu,std::size_t n,int reps,std::ofstream&out){std::vector<float>a(n,1.25f),b(n,2.5f),h(n);Device<float>da(n),db(n),dc(n);check(cudaMemset(dc.p,0,n*sizeof(float)));auto h2d=host_median([&]{check(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));check(cudaMemcpy(db.p,b.data(),n*sizeof(float),cudaMemcpyHostToDevice));},reps);auto d2h=host_median([&]{check(cudaMemcpy(h.data(),dc.p,n*sizeof(float),cudaMemcpyDeviceToHost));},reps);auto cpu=cpu_median([&]{cudaforge::cpu::vector_add_parallel(a.data(),b.data(),h.data(),n);},reps);
 for(int opt=0;opt<2;++opt){auto launch=[&]{if(opt)cudaforge::cuda::vector_add_optimized(da.p,db.p,dc.p,n);else cudaforge::cuda::vector_add_naive(da.p,db.p,dc.p,n);};auto kt=event_samples(launch,reps);auto e2e=host_median([&]{check(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));check(cudaMemcpy(db.p,b.data(),n*sizeof(float),cudaMemcpyHostToDevice));launch();check(cudaMemcpy(h.data(),dc.p,n*sizeof(float),cudaMemcpyDeviceToHost));},reps);emit(out,"vector_add",opt?"optimized":"naive",gpu,n,reps,median(kt),h2d,d2h,e2e,cpu);}}
void run_reduction(const char*gpu,std::size_t n,int reps,std::ofstream&out,bool maximum){std::vector<float>a(n,1.25f);Device<float>da(n),scratch_max(n);Device<double>scratch_sum(n),dsum(1);Device<float>dmax(1);double hsum=0;float hmax=0;check(cudaMemset(dsum.p,0,sizeof(double)));check(cudaMemset(dmax.p,0,sizeof(float)));auto h2d=host_median([&]{check(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));},reps);auto d2h=maximum?host_median([&]{check(cudaMemcpy(&hmax,dmax.p,sizeof(float),cudaMemcpyDeviceToHost));},reps):host_median([&]{check(cudaMemcpy(&hsum,dsum.p,sizeof(double),cudaMemcpyDeviceToHost));},reps);auto cpu=maximum?cpu_median([&]{hmax=cudaforge::cpu::reduce_max_parallel(a.data(),n);},reps):cpu_median([&]{hsum=cudaforge::cpu::reduce_sum_parallel(a.data(),n);},reps);
 auto launch=[&]{if(maximum)cudaforge::cuda::reduce_max_device(da.p,dmax.p,scratch_max.p,n);else cudaforge::cuda::reduce_sum_device(da.p,dsum.p,scratch_sum.p,n);};auto kt=event_samples(launch,reps);auto e2e=host_median([&]{check(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));launch();if(maximum)check(cudaMemcpy(&hmax,dmax.p,sizeof(float),cudaMemcpyDeviceToHost));else check(cudaMemcpy(&hsum,dsum.p,sizeof(double),cudaMemcpyDeviceToHost));},reps);emit(out,maximum?"maximum":"sum","shared_reduce",gpu,n,reps,median(kt),h2d,d2h,e2e,cpu);}
void run_scan(const char*gpu,std::size_t n,int reps,std::ofstream&out,bool naive){std::vector<float>a(n,1.f),h(n);Device<float>da(n),dy(n),scratch((n+255)/256);check(cudaMemset(dy.p,0,n*sizeof(float)));auto h2d=host_median([&]{check(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));},reps);auto d2h=host_median([&]{check(cudaMemcpy(h.data(),dy.p,n*sizeof(float),cudaMemcpyDeviceToHost));},reps);auto cpu=cpu_median([&]{cudaforge::cpu::inclusive_scan_parallel(a.data(),h.data(),n);},reps);auto launch=[&]{if(naive)cudaforge::cuda::inclusive_scan_naive(da.p,dy.p,n);else cudaforge::cuda::inclusive_scan_optimized_device(da.p,dy.p,scratch.p,n);};auto kt=event_samples(launch,reps);auto e2e=host_median([&]{check(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));launch();check(cudaMemcpy(h.data(),dy.p,n*sizeof(float),cudaMemcpyDeviceToHost));},reps);emit(out,"inclusive_scan",naive?"naive":"tiled",gpu,n,reps,median(kt),h2d,d2h,e2e,cpu);}
void run_matmul(const char*gpu,std::size_t side,int reps,std::ofstream&out,bool optimized){std::size_t count=side*side;std::vector<float>a(count,1.25f),b(count,.5f),h(count);Device<float>da(count),db(count),dc(count);check(cudaMemset(dc.p,0,count*sizeof(float)));auto h2d=host_median([&]{check(cudaMemcpy(da.p,a.data(),count*sizeof(float),cudaMemcpyHostToDevice));check(cudaMemcpy(db.p,b.data(),count*sizeof(float),cudaMemcpyHostToDevice));},reps);auto d2h=host_median([&]{check(cudaMemcpy(h.data(),dc.p,count*sizeof(float),cudaMemcpyDeviceToHost));},reps);auto cpu=cpu_median([&]{cudaforge::cpu::matmul_parallel(a.data(),b.data(),h.data(),side,side,side);},reps);auto launch=[&]{if(optimized)cudaforge::cuda::matmul_optimized(da.p,db.p,dc.p,side,side,side);else cudaforge::cuda::matmul_naive(da.p,db.p,dc.p,side,side,side);};auto kt=event_samples(launch,reps);auto e2e=host_median([&]{check(cudaMemcpy(da.p,a.data(),count*sizeof(float),cudaMemcpyHostToDevice));check(cudaMemcpy(db.p,b.data(),count*sizeof(float),cudaMemcpyHostToDevice));launch();check(cudaMemcpy(h.data(),dc.p,count*sizeof(float),cudaMemcpyDeviceToHost));},reps);emit(out,"matmul",optimized?"tiled":"naive",gpu,side,reps,median(kt),h2d,d2h,e2e,cpu);}
}
int main(int argc,char**argv){try{int reps=argc>1?std::max(1,std::atoi(argv[1])):101;std::string path=argc>2?argv[2]:"cudaforge_gpu_results.csv";int count=0;check(cudaGetDeviceCount(&count));if(count==0)throw std::runtime_error("No CUDA device available; run this benchmark on a GPU host.");cudaDeviceProp prop{};check(cudaGetDeviceProperties(&prop,0));check(cudaSetDevice(0));std::ofstream out(path);if(!out)throw std::runtime_error("Cannot open output CSV: "+path);out<<"algorithm,implementation,gpu_model,n,repetitions,kernel_median_ms,h2d_median_ms,d2h_median_ms,end_to_end_median_ms,cpu_median_ms,speedup_end_to_end\n";std::cout<<"GPU: "<<prop.name<<"; repetitions: "<<reps<<"; output: "<<path<<'\n';for(std::size_t n:{1024u,4096u,16384u,262144u}){run_vector(prop.name,n,reps,out);run_reduction(prop.name,n,reps,out,false);run_reduction(prop.name,n,reps,out,true);run_scan(prop.name,n,reps,out,false);if(n<=4096)run_scan(prop.name,n,reps,out,true);}for(std::size_t side:{32u,64u,128u}){run_matmul(prop.name,side,reps,out,false);run_matmul(prop.name,side,reps,out,true);}check(cudaDeviceSynchronize());std::cout<<"Completed GPU benchmark rows: "<<path<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"CUDA benchmark failed: "<<e.what()<<'\n';return 1;}}
